#!/usr/bin/env python3
"""Fixture generator: build/m1_test/map_99.bin (12x12 test map, contract 3.1) for gate G2 and the
host harness.  Small on purpose -- the official compiler is tools/mapc.py.

Writes build/m1_test/** (generated iso boxes + catalog.toml and the v1 fixture map_99.bin; since contract 49 nothing is written to nucleo/files).
  python3 tools/make_test_map.py [--out nucleo/files/map_99.bin]
"""
import argparse
import os
import struct
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
REPO = os.path.dirname(HERE)
sys.path.insert(0, HERE)
import lvlib  # noqa: E402
import spritec  # noqa: E402

W = H = 12
ART = os.path.join(REPO, "build", "m1_test")


# ---------------------------------------------------------------- generated art
def iso_box(fw, fh, hgt, name, windows=True):
    """fw x fh tile footprint, `hgt` px tall.  Anchor = integer pixel at the footprint's bottom
    vertex (front tile centre + (0, 7)), so ay = h - 1 (the vertex pixel is the last row)."""
    Wd = (fw + fh) * 14 + 1
    Ht = (fw + fh) * 7 + 1 + hgt
    ax, ay = fw * 14, Ht - 1
    face = [[0] * Wd for _ in range(Ht)]  # 0 none, 1 top, 2 left, 3 right
    for py in range(Ht):
        for px in range(Wd):
            dx, dy = px - ax, py - ay      # pixel centre relative to the anchor pixel
            ty = dy + hgt                   # undo the lift: ground-plane position of the top face
            u = (dx / 14 + ty / 7) / 2
            v = (ty / 7 - dx / 14) / 2
            if -fw - 1e-9 <= u <= 1e-9 and -fh - 1e-9 <= v <= 1e-9:
                face[py][px] = 1
            elif -fw * 14 <= dx <= 0 and dx / 2 - hgt < dy <= dx / 2:
                face[py][px] = 2            # left face (v = 0 plane)
            elif 0 < dx <= fh * 14 and -dx / 2 - hgt < dy <= -dx / 2:
                face[py][px] = 3            # right face (u = 0 plane)
    lv = [[0] * Wd for _ in range(Ht)]
    mk = [[1 if face[y][x] else 0 for x in range(Wd)] for y in range(Ht)]
    shade = {1: 0, 2: 1, 3: 2}
    for y in range(Ht):
        for x in range(Wd):
            lv[y][x] = shade.get(face[y][x], 0)
    if windows and hgt >= 14:
        for y in range(Ht):
            for x in range(Wd):
                f = face[y][x]
                if f not in (2, 3):
                    continue
                dx, dy = x - ax, y - ay
                s_ = (dx / 14) if f == 2 else (-dx / 14)
                z = (dx / 2 - dy) if f == 2 else (-dx / 2 - dy)
                fr = s_ - int(s_ // 1)
                if 0.35 <= fr <= 0.65 and 0.4 * hgt <= z <= 0.7 * hgt:
                    lv[y][x] = 3
    for y in range(Ht):
        for x in range(Wd):
            if not mk[y][x]:
                continue
            edge = False
            for dx_, dy_ in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                xx, yy = x + dx_, y + dy_
                if not (0 <= xx < Wd and 0 <= yy < Ht) or not mk[yy][xx]:
                    edge = True
                elif face[y][x] == 1 and face[yy][xx] != 1:
                    edge = True
            if edge:
                lv[y][x] = 3
    path = os.path.join(ART, name + ".lv.png")
    lvlib.write_lv_png(path, lv, mk, ax, ay, force=True)
    return path


def tile_diamond(name, level, fleck):
    """28x15 ground tile, anchor (14, 7) = tile centre pixel."""
    d = [[abs(x + .5 - 14) / 14 + abs(y - 7) / 7.5 <= 1 for x in range(28)] for y in range(15)]
    lv = [[(level if d[y][x] and not fleck else 0) for x in range(28)] for y in range(15)]
    if fleck:
        for y in range(15):
            for x in range(28):
                if d[y][x] and (x * 7 + y * 3) % 11 == 0:
                    lv[y][x] = 1
    mk = [[1 if d[y][x] else 0 for x in range(28)] for y in range(15)]
    lvlib.write_lv_png(os.path.join(ART, name + ".lv.png"), lv, mk, 14, 7, force=True)


CATALOG = """# generated by tools/make_test_map.py
[[sprite]]
name = "grass"
kind = "tile"
src = "grass.lv.png"
cflags = ["grass"]

[[sprite]]
name = "path"
kind = "tile"
src = "path.lv.png"
fill = 1

[[sprite]]
name = "house2x2"
kind = "object"
src = "house2x2.lv.png"
fw = 2
fh = 2
cflags = ["solid"]

[[sprite]]
name = "wall3x2"
kind = "object"
src = "wall3x2.lv.png"
fw = 3
fh = 2
cflags = ["solid"]

[[sprite]]
name = "crate"
kind = "object"
src = "crate.lv.png"
cflags = ["solid"]

[[sprite]]
name = "mama"
kind = "actor"
src = "../../assets/art/npcs/mama"
ndirs = 8
nframes = 1

[[sprite]]
name = "lin"
kind = "actor"
src = "../../assets/art/npcs/lin"
ndirs = 8
nframes = 1
"""


# ---------------------------------------------------------------- map
def build_map(out_path, iso=None):
    os.makedirs(ART, exist_ok=True)
    tile_diamond("grass", 0, True)
    tile_diamond("path", 1, False)
    iso_box(2, 2, 30, "house2x2")
    iso_box(3, 2, 22, "wall3x2")
    iso_box(1, 1, 16, "crate", windows=False)
    cat_path = os.path.join(ART, "catalog.toml")
    with open(cat_path, "w") as f:
        f.write(CATALOG)
    cat = spritec.load_catalog(cat_path)
    names = ["grass", "path", "house2x2", "wall3x2", "crate", "mama", "lin"]
    bank, idx = spritec.build_bank(cat, names)
    ent = {n: cat.entry(n) for n in names}

    ground = bytearray([idx["grass"]] * (W * H))
    for i in range(W):                         # a path along j = 8 and i = 2
        ground[8 * W + i] = idx["path"]
    for j in range(H):
        ground[j * W + 2] = idx["path"]
    for (i, j) in ((11, 11), (11, 10), (10, 11)):  # holes: bg colour shows
        ground[j * W + i] = 0xFF
    cflags = bytearray(W * H)
    for k in range(W * H):
        cflags[k] = ent["grass"].cflags if ground[k] == idx["grass"] else 0

    objs = [("house2x2", 5, 4), ("wall3x2", 0, 0), ("crate", 8, 3), ("crate", 9, 3), ("crate", 3, 5),
            ("house2x2", 7, 6)]
    if iso:  # isolated building for the host depth-sort proof (map_98 / map_97, host only)
        objs = [("house2x2", 5, 4)] if iso == "house" else [("wall3x2", 4, 4)]
    objs.sort(key=lambda o: (o[1] + ent[o[0]].fw - 1) + (o[2] + ent[o[0]].fh - 1))
    for n, i0, j0 in objs:
        e = ent[n]
        for j in range(j0, j0 + e.fh):
            for i in range(i0, i0 + e.fw):
                cflags[j * W + i] |= e.cflags
    obj_b = b"".join(struct.pack("<4B", idx[n], i0, j0, 0) for n, i0, j0 in objs)

    # NpcDef: spr,i,j,facing,behavior,flags,text_id,show,hide,param,talk
    npcs = [("mama", 4, 9, 7, 0, 1, 0), ("lin", 9, 9, 3, 1, 1, 1)]
    if iso:
        npcs = []
    npc_b = b"".join(struct.pack("<6BH4B", idx[n], i, j, fc, bh, fl, tid, 0, 0, 4, 0)
                     for n, i, j, fc, bh, fl, tid in npcs)
    warp_b = struct.pack("<8B", 10, 0, 1, 3, 3, 0, 0, 0xFF)
    cflags[0 * W + 10] |= 16
    int_b = struct.pack("<5BHB", 4, 4, 0xFF, 0, 0, 2, 0)  # mode 0 text 2 at (4,4)
    spw_b = struct.pack("<4B", 0, 6, 8, 0) + struct.pack("<4B", 1, 2, 10, 2)

    def pad4(b):
        return b + b"\0" * ((-len(b)) % 4)

    secs = [bytes(ground), bytes(cflags), obj_b, npc_b, warp_b, int_b, spw_b]
    off = 64
    offs = []
    body = b""
    for s in secs:
        offs.append(off)
        s = pad4(s)
        body += s
        off += len(s)
    off_bank = off
    total = off_bank + len(bank)
    hdr = bytearray(64)
    hdr[0:4] = b"NMAP"
    hdr[4], hdr[5], hdr[6], hdr[7], hdr[8], hdr[9] = 1, {None: 99, 'house': 98, 'wall': 97}[iso], W, H, 3, 0
    struct.pack_into("<H4B", hdr, 12, len(objs), len(npcs), 1, 1, 2)
    struct.pack_into("<8I", hdr, 20, *offs, off_bank)
    struct.pack_into("<I", hdr, 52, total)
    data = bytes(hdr) + body + bank
    assert len(data) == total
    os.makedirs(os.path.dirname(os.path.abspath(out_path)), exist_ok=True)
    with open(out_path, "wb") as f:
        f.write(data)
    return total, len(bank), idx


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=os.path.join(ART, "map_99.bin"))   # C6 (contract 49): the v1 fixture lives in build/m1_test only (nucleo/files must not hold an id-99 file: MAP_COUNT has a hole there)
    a = ap.parse_args()
    total, nb, idx = build_map(a.out)
    os.makedirs(ART, exist_ok=True)
    build_map(os.path.join(ART, "map_98.bin"), iso="house")  # isolated buildings for the host sort proof
    build_map(os.path.join(ART, "map_97.bin"), iso="wall")
    print(f"wrote {a.out}: {total} bytes (bank {nb}), sprites {idx}")
